/* Original bonus primitives and bounded, ordered texture layers. */
#include <SDL.h>
#include <stdio.h>
#include <stdlib.h>
int main(int argc,char**argv){if(argc!=5&&argc!=9)return 1;int mode=atoi(argv[1]),ox=atoi(argv[2]),oy=atoi(argv[3]);unsigned long bg=strtoul(argv[4],NULL,16);
SDL_Surface*s=NULL;SDL_Window*window=NULL;SDL_Renderer*r=NULL;SDL_Texture*target=NULL;
if(getenv("GAMEPKG_BONUS_SOFTWARE")){s=SDL_CreateRGBSurfaceWithFormat(0,41,41,32,SDL_PIXELFORMAT_RGBA32);if(!s)return 2;r=SDL_CreateSoftwareRenderer(s);}else{if(SDL_Init(SDL_INIT_VIDEO))return 13;window=SDL_CreateWindow("bonus-reference",0,0,41,41,SDL_WINDOW_HIDDEN);if(!window)return 14;r=SDL_CreateRenderer(window,-1,SDL_RENDERER_TARGETTEXTURE);if(!r)return 15;SDL_RendererInfo info;if(SDL_GetRendererInfo(r,&info)||SDL_strcmp(info.name,"opengl"))return 16;target=SDL_CreateTexture(r,SDL_PIXELFORMAT_RGBA8888,SDL_TEXTUREACCESS_TARGET,41,41);if(!target||SDL_SetRenderTarget(r,target))return 17;}if(!r)return 3;SDL_SetRenderDrawColor(r,bg>>24,bg>>16,bg>>8,bg);SDL_RenderClear(r);SDL_SetRenderDrawBlendMode(r,mode==2||mode==5?SDL_BLENDMODE_BLEND:SDL_BLENDMODE_NONE);
char op;int layer,x,y,w,h,red,green,blue,a;while(scanf(" %c %d %d %d %d %d %d %d %d %d",&op,&layer,&x,&y,&w,&h,&red,&green,&blue,&a)==10){if(mode!=5&&mode!=layer)continue;SDL_SetRenderDrawColor(r,red,green,blue,a);int result=0;if(op=='P')result=SDL_RenderDrawPoint(r,x-ox,y-oy);else if(op=='R'){SDL_Rect q={x-ox,y-oy,w,h};result=SDL_RenderFillRect(r,&q);}else return 4;if(result)return 5;}
if(mode==4){if(argc!=9)return 6;for(int i=0;i<4;i++){unsigned char pixels[41*41*4];FILE*f=fopen(argv[5+i],"rb");if(!f||fread(pixels,1,sizeof(pixels),f)!=sizeof(pixels))return 7;fclose(f);SDL_Surface*l=SDL_CreateRGBSurfaceWithFormatFrom(pixels,41,41,32,41*4,SDL_PIXELFORMAT_RGBA32);if(!l)return 8;SDL_Texture*t=SDL_CreateTextureFromSurface(r,l);if(!t)return 9;SDL_SetTextureBlendMode(t,SDL_BLENDMODE_BLEND);SDL_SetTextureScaleMode(t,SDL_ScaleModeNearest);SDL_Rect q={0,0,41,41};if(SDL_RenderCopy(r,t,NULL,&q))return 10;SDL_DestroyTexture(t);SDL_FreeSurface(l);}}
unsigned char out[41*41*4];if(SDL_RenderReadPixels(r,NULL,SDL_PIXELFORMAT_RGBA32,out,41*4))return 11;if(fwrite(out,1,sizeof(out),stdout)!=sizeof(out))return 12;if(target)SDL_DestroyTexture(target);SDL_DestroyRenderer(r);if(window)SDL_DestroyWindow(window);if(s)SDL_FreeSurface(s);SDL_Quit();return 0;}
